'use client'

import { useEffect, useState } from 'react'

const sections = [
  { key: 'analytics', title: 'Analytics', endpoint: '/api/analytics' },
  { key: 'notifications', title: 'Notifications', endpoint: '/api/notifications' },
  { key: 'settings', title: 'Settings', endpoint: '/api/settings' },
] as const

type SectionKey = (typeof sections)[number]['key']
type SectionResult = { data: unknown } | { error: string }
type DashboardData = Partial<Record<SectionKey, SectionResult>>

async function fetchSection(
  endpoint: string,
  signal: AbortSignal,
): Promise<SectionResult> {
  try {
    const response = await fetch(endpoint, { signal })

    if (!response.ok) {
      throw new Error(`Request failed (${response.status})`)
    }

    return { data: await response.json() }
  } catch (error) {
    return {
      error: error instanceof Error ? error.message : 'Unable to load data',
    }
  }
}

export default function Dashboard() {
  const [data, setData] = useState<DashboardData>({})

  useEffect(() => {
    const controller = new AbortController()

    async function loadDashboard() {
      const results = await Promise.all(
        sections.map(async ({ key, endpoint }) => {
          const result = await fetchSection(endpoint, controller.signal)
          return [key, result] as const
        }),
      )

      if (!controller.signal.aborted) {
        setData(Object.fromEntries(results) as DashboardData)
      }
    }

    void loadDashboard()

    return () => controller.abort()
  }, [])

  return (
    <section aria-labelledby="dashboard-content-heading">
      <h2 id="dashboard-content-heading">Dashboard Content</h2>
      <div>
        {sections.map(({ key, title }) => {
          const result = data[key]

          return (
            <section key={key} aria-labelledby={`${key}-heading`}>
              <h3 id={`${key}-heading`}>{title}</h3>
              {!result ? (
                <p role="status">Loading {title.toLowerCase()}...</p>
              ) : 'error' in result ? (
                <p role="alert">
                  Could not load {title.toLowerCase()}: {result.error}
                </p>
              ) : (
                <pre>{JSON.stringify(result.data, null, 2)}</pre>
              )}
            </section>
          )
        })}
      </div>
    </section>
  )
}

